window.__votdWeek && window.__votdWeek({"week":"2028-10-02","reading":"3 Nephi 17–19","days":[{"d":"2028-10-02","ref":"3 Nephi 17:2","b":"3 Nephi","c":17,"v":2,"he":"רֹאֶה אֲנִי כִּי חַלָּשִׁים אַתֶּם וְלֹא תוּכְלוּ לְהָבִין אֶת־כׇּל־דְּבָרַי אֲשֶׁר צִוַּנִי הָאָב לְדַבֵּר אֲלֵיכֶם בָּעֵת הַזֹּאת׃","en":"I perceive that ye are weak, that ye cannot understand all my words which I am commanded of the Father to speak unto you at this time."},{"d":"2028-10-03","ref":"3 Nephi 17:3","b":"3 Nephi","c":17,"v":3,"he":"לָכֵן לְכוּ לְבָתֵּיכֶם וְהָגוּ בַדְּבָרִים אֲשֶׁר דִּבַּרְתִּי וְשַׁאֲלוּ מֵאֵת הָאָב בִּשְׁמִי לְמַעַן תָּבִינוּ וְהָכִינוּ אֶת־לִבְּכֶם לְמָחָר וְאָשׁוּב אֲלֵיכֶם׃","en":"Therefore, go ye unto your homes, and ponder upon the things which I have said, and ask of the Father, in my name, that ye may understand, and prepare your minds for the morrow, and I come unto you again."},{"d":"2028-10-04","ref":"3 Nephi 18:20","b":"3 Nephi","c":18,"v":20,"he":"וְכׇל־אֲשֶׁר תִּשְׁאֲלוּ מֵאֵת הָאָב בִּשְׁמִי אֲשֶׁר יָשָׁר בַּאֲמִינְכֶם כִּי תְקַבֵּלוּ הִנֵּה יִנָּתֵן לָכֶם׃","en":"And whatsoever ye shall ask the Father in my name, which is right, believing that ye shall receive, behold it shall be given unto you."},{"d":"2028-10-05","ref":"3 Nephi 18:24","b":"3 Nephi","c":18,"v":24,"he":"לָכֵן הָרִימוּ אוֹרְכֶם לְמַעַן יָאִיר לָעוֹלָם הִנֵּה אָנֹכִי הָאוֹר אֲשֶׁר תָּרִימוּ הוּא אֲשֶׁר רְאִיתֶם אוֹתִי עֹשֶׂה הִנֵּה רְאִיתֶם כִּי הִתְפַּלַּלְתִּי אֶל־הָאָב וְכֻלְּכֶם עֵדִים׃","en":"Therefore, hold up your light that it may shine unto the world. Behold I am the light which ye shall hold up—that which ye have seen me do. Behold ye see that I have prayed unto the Father, and ye all have witnessed."},{"d":"2028-10-06","ref":"3 Nephi 18:38","b":"3 Nephi","c":18,"v":38,"he":"וַיְהִי כַּאֲשֶׁר נָגַע בְּכֻלָּם וַיָּבֹא עָנָן וַיְכַס אֶת־הַקָּהָל וְלֹא יָכְלוּ לִרְאוֹת אֶת־יֵשׁוּעַ׃","en":"And it came to pass that when Jesus had touched them all, there came a cloud and overshadowed the multitude that they could not see Jesus."},{"d":"2028-10-07","ref":"3 Nephi 19:32","b":"3 Nephi","c":19,"v":32,"he":"וְלֹא תוּכַל לָשׁוֹן לְדַבֵּר אֶת־הַדְּבָרִים אֲשֶׁר הִתְפַּלֵּל וְלֹא־יוּכַל אָדָם לִכְתֹּב אֶת־הַדְּבָרִים אֲשֶׁר הִתְפַּלֵּל׃","en":"And tongue cannot speak the words which he prayed, neither can be written by man the words which he prayed."},{"d":"2028-10-08","ref":"3 Nephi 19:33","b":"3 Nephi","c":19,"v":33,"he":"וַיִּשְׁמַע הַקָּהָל וַיָּעִידוּ וַיִּפָּתְחוּ לִבּוֹתָם וַיָּבִינוּ בִלְבָבָם אֶת־הַדְּבָרִים אֲשֶׁר הִתְפַּלֵּל׃","en":"And the multitude did hear and do bear record; and their hearts were open and they did understand in their hearts the words which he prayed."}]});
